<?php
require_once __DIR__.'/inc/functions.php';
require_once __DIR__.'/inc/TransferPurchases.php';
header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');header('X-Frame-Options: DENY');
$id=$_GET['order']??'';if(!is_string($id)||!preg_match('/^ORD-[0-9]{8}-[a-f0-9]{16}$/D',$id))AccessControl::deny();
$admin=isMainAdmin();if(!$admin&&empty($_SESSION['transfer_orders'][$id]))AccessControl::deny();
$service=new TransferPurchases();try{$row=$service->order($id);}catch(RuntimeException $e){http_response_code(404);exit('سفارش یافت نشد.');}
if(isset($_GET['image'])){try{$file=$service->receiptPath($row);if(!is_file($file))throw new RuntimeException();header('Content-Type: '.$row['evidence']['mime']);header('X-Content-Type-Options: nosniff');header('Content-Disposition: inline; filename="receipt"');readfile($file);exit;}catch(Throwable $e){http_response_code(404);exit('رسید یافت نشد.');}}
$error='';if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 RequestSecurity::enforce();try{if(isset($_POST['review'])){if(!$admin)AccessControl::deny();if(!in_array($_POST['review'],['approve','reject'],true))throw new RuntimeException('تصمیم معتبر نیست.');$service->review($id,$_POST['review']==='approve',$_POST['note']??'');}else{if($admin)throw new RuntimeException('ثبت رسید توسط خریدار انجام می‌شود.');$service->upload($id,$_POST,$_FILES['receipt']??[]);}redirect('transfer-payment.php?order='.rawurlencode($id));}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'ثبت انجام نشد؛ دوباره تلاش کنید.';}
 $row=$service->order($id);
}
$o=$row['receipt'];$d=$row['destination'];function transfer_h($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>پرداخت کارت‌به‌کارت</title><link rel="stylesheet" href="assets/project-onboarding.css?v=<?=filemtime(__DIR__.'/assets/project-onboarding.css')?>"></head><body><main class="setup-shell"><section class="setup-main" style="max-width:760px;margin:24px auto"><h1>پرداخت کارت‌به‌کارت</h1><p>سفارش <?=transfer_h($id)?> · <?=transfer_h($o['plan_name'])?> · <?=number_format($o['amount'])?> تومان</p><p role="status"><?php echo ['pending'=>'در انتظار ثبت رسید','awaiting_review'=>'رسید دریافت شد؛ در انتظار تأیید مدیر','rejected'=>'رسید رد شده؛ دلیل را ببینید و رسید اصلاح‌شده ثبت کنید.','completed'=>'پرداخت تأیید و پروژه فعال شد.'][$o['status']]??'نامشخص';?></p><?php if($error):?><p role="alert"><?=transfer_h($error)?></p><?php endif;?>
<div class="setup-guide"><h2>حساب مقصد</h2><p>بانک: <?=transfer_h($d['bank']??'')?> · صاحب حساب: <?=transfer_h($d['holder'])?></p><p>کارت: <b dir="ltr"><?=transfer_h($d['card'])?></b></p><p>شبا: <b dir="ltr"><?=transfer_h($d['iban']??'')?></b></p><p style="white-space:pre-wrap"><?=transfer_h($d['instructions']??'')?></p><small>مبلغ به تومان است. شماره کارت کامل مبدأ یا رمز بانکی خود را وارد نکنید.</small></div>
<?php if(!empty($row['review'])):?><div class="setup-guide"><h2>نتیجهٔ بررسی</h2><p><?=transfer_h($row['review']['note'])?></p></div><?php endif;?>
<?php if(!empty($row['evidence'])):$e=$row['evidence'];?><div class="setup-guide"><h2>رسید ثبت‌شده</h2><p>چهار رقم آخر کارت: <?=transfer_h($e['last_four'])?> · پیگیری: <?=transfer_h($e['reference'])?> · زمان واریز: <?=transfer_h($e['paid_date'])?></p><a target="_blank" rel="noopener" href="?order=<?=rawurlencode($id)?>&image=1">مشاهدهٔ تصویر رسید</a></div><?php endif;?>
<form method="post" enctype="multipart/form-data"><input type="hidden" name="app_csrf" value="<?=transfer_h(RequestSecurity::token())?>"><?php if($admin&&$o['status']==='awaiting_review'):?><label>توضیح بررسی (برای رد الزامی)<textarea name="note" maxlength="2000"></textarea></label><div class="setup-actions"><button name="review" value="approve">تأیید و فعال‌سازی پروژه</button><button name="review" value="reject" class="secondary">رد رسید</button></div><?php elseif(!$admin&&in_array($o['status'],['pending','rejected'],true)):?><label>چهار رقم آخر کارت مبدأ<input name="last_four" required pattern="[0-9۰-۹]{4}" maxlength="4" inputmode="numeric"></label><label>شماره پیگیری واریز<input name="reference" required maxlength="100"></label><label>تاریخ و ساعت واریز<input name="paid_date" required maxlength="100" placeholder="۱۴۰۵/۰۸/۰۱ ساعت ۱۲:۳۰"></label><label>تصویر رسید (حداکثر ۵ مگابایت)<input type="file" name="receipt" accept="image/jpeg,image/png,image/webp" required></label><button>ثبت رسید برای بررسی</button><?php endif;?></form>
<?php if($o['status']==='completed'):?><a class="setup-button" href="/index.php?action=login">ورود به حساب و راه‌اندازی پروژه</a><?php endif;?><p><a href="<?=$admin?'admin.php?tab=main_orders':'/index.php'?>">بازگشت</a></p><small>کد سفارش را نگه دارید. پیگیری قبل از فعال‌سازی از همین مرورگر امکان‌پذیر است.</small></section></main></body></html>
